  .hud-brand{font-size:13px}
  .hud-hp{width:170px}
  .map-layout{grid-template-columns:minmax(0,1fr) 280px;gap:12px;padding:12px}
  .side-card{padding:11px}
  .title-content{margin-left:6vw}
}
@media (max-width:900px){
  .map-layout{grid-template-columns:1fr}
  .map-side{display:none}
  .map-scroll{height:900px;min-width:340px}
