  .starter-card .starter-deck{margin-top:4px;padding-top:4px}
  .starter-card .starter-pick{grid-column:2;margin-top:4px}
  .starter-hp{justify-content:flex-start}
  .how-grid{grid-template-columns:1fr}
}
