  .status-pill b{font-size:7px}
  .intent-card{padding:3px 7px 3px 4px;gap:5px;min-width:84px}
  .intent-icon{width:23px;height:23px;font-size:11px}
  .intent-copy span{font-size:6px}
  .intent-copy b{font-size:12px}
  .intent-name{display:none}
  .catch-hint{font-size:6.5px;margin-top:3px}
  .battle-mid{padding:1px 2px;gap:4px;min-height:48px}
  .ball-dock{padding:3px 5px;gap:4px;border-radius:8px}
  .ball-dock-label{font-size:6.5px;letter-spacing:.08em}
  .ball-dock-label span{display:none}
  .ball-btn{min-width:0;padding:4px 5px;gap:3px}
  .ball-btn .ball-icon{width:14px;height:14px}
  .ball-btn-copy b{font-size:8px}
  .ball-btn-copy span{font-size:7px}
  .ball-btn .ball-count{display:none}
  .combat-log{display:none}
  .battle-actions{gap:4px}
  .btn-view-deck-battle{display:none}
  .btn-end{padding:8px 10px;font-size:9px;gap:4px}
