  .hand-zone{flex:0 0 176px;gap:3px;padding-bottom:calc(2px + var(--safe-bottom))}
  .hand{padding-top:14px;overflow-x:auto;overflow-y:hidden;justify-content:flex-start;width:100%;scrollbar-width:none}
  .hand::-webkit-scrollbar{display:none}
  .card{width:106px;height:151px;border-radius:8px}
  .card-inner{padding:5px}
  .card-cost{width:18px;height:18px;font-size:10px}
  .card-name{font-size:8px}
  .card-type{width:14px;height:14px;font-size:7px}
  .card-art{height:44px;margin:3px 0}
  .card-art .art-mon{width:40px;height:40px}
  .card-art .art-icon{font-size:23px}
  .card-art .art-icon svg{width:23px;height:23px}
  .card-text{font-size:7px;line-height:1.3}
  .card-foot{font-size:5.5px;margin-top:2px;padding-top:2px}
  .card-upgraded{width:15px;height:15px;font-size:9px;top:-4px;right:-4px}
  .pile{width:40px;height:56px;border-radius:6px}
  .pile-count{font-size:14px}
