  .title-mon img{width:54px}
  .title-actions{gap:8px}
  .title-actions .btn-large{font-size:13px;padding:12px 18px}
  .title-features{display:none}
  .title-footer{left:6vw;right:6vw;font-size:8px;line-height:1.4}
  .title-footer>span:first-child{max-width:70%}
  .title-footer .footer-dot{display:none}
  .eyebrow{font-size:8px;letter-spacing:.18em;gap:8px}
  .eyebrow-line{width:22px}
  .how-grid{gap:7px}
}
@media (max-height:680px) and (min-width:761px){
  .battle-stage{min-height:210px;max-height:280px}
  .hand-zone{flex-basis:180px}
  .card{width:124px;height:174px}
  .card-art{height:50px}
  .card-text{font-size:7.5px}
  .map-scroll{height:900px}
}
@media (max-height:560px) and (max-width:900px){
  .battle-stage{min-height:150px;max-height:210px}
  .hand-zone{flex-basis:142px}
  .card{width:92px;height:132px}
  .card-art{height:36px}
  .card-text{font-size:6.2px}
  .combatant-panel{padding:4px 6px}
  .battle-mid{min-height:42px}
  .hand{padding-top:8px}
  .catch-hint{display:none}
}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation-duration:.001ms!important;animation-iteration-count:1!important;transition-duration:.001ms!important}
}

