    if (card) playCard(card.uid);
  } else if (e.key.toLowerCase() === 'd') {
    openDeckModal();
  } else if (e.key.toLowerCase() === 'p') {
    openPartyModal();
  }
}

/* ============================================================
   Screen / title / save
   ============================================================ */
function setScreen(name) {
  state.screen = name;
  $$('.screen').forEach(el => el.classList.toggle('active', el.id === 'screen-' + name));
