  updateSoundButtons();
}
function refreshContinueButton() {
  const btn = $('#btn-continue');
  if (!btn) return;
  btn.classList.toggle('hidden', !hasSave());
}
function hasSave() {
  try {
    const raw = localStorage.getItem(SAVE_KEY);
    if (!raw) return false;
    const data = JSON.parse(raw);
    return data && data.version === 1 && data.deck?.length;
  } catch { return false; }
}
