+      if (v > 0) applyEnemyStatus(k, v);
+    }
+    if (stats.draw > 0) drawCards(stats.draw);
+    if (stats.energy > 0) { b.player.energy += stats.energy; spawnFloat($('#player-side'), `+${stats.energy} ENERGY`, 'status'); }
